def _grant_notice_tag_permissions(permissions):
    if not isinstance(permissions, list):
        return permissions, False
    next_permissions = list(permissions)
    changed = False
    if "notice.view" in next_permissions or "notice.manage" in next_permissions:
        for key in ("notice.stats.view", "notice.tag.view"):
            if key not in next_permissions:
                next_permissions.append(key)
                changed = True
    if "notice.manage" in next_permissions and "notice.tag.manage" not in next_permissions:
        next_permissions.append("notice.tag.manage")
        changed = True
    return next_permissions, changed


def grant_notice_tag_access(apps, schema_editor):
    RoleRecord = apps.get_model("data_store", "RoleRecord")
    AppState = apps.get_model("data_store", "AppState")
    NavMenuItemRecord = apps.get_model("data_store", "NavMenuItemRecord")

    for role in RoleRecord.objects.all():
        data = dict(role.data or {})
        permissions, changed = _grant_notice_tag_permissions(list(data.get("permissions") or []))
        if not changed:
            continue
        data["permissions"] = permissions
        role.data = data
        role.save(update_fields=["data"])

    for state in AppState.objects.all():
        payload = dict(state.data or {})
        roles = payload.get("roles")
        if not isinstance(roles, list):
            continue
        changed = False
        next_roles = []
        for role in roles:
            if not isinstance(role, dict):
                next_roles.append(role)
                continue
            permissions, role_changed = _grant_notice_tag_permissions(list(role.get("permissions") or []))
            if role_changed:
                changed = True
                next_roles.append({**role, "permissions": permissions})
            else:
                next_roles.append(role)
        if changed:
            payload["roles"] = next_roles
            state.data = payload
            state.save(update_fields=["data"])

    rows = {row["id"]: row for row in DEFAULT_NAV_ITEMS}
    for item_id in ("nav-item-noticeStats", "nav-item-noticeTags"):
        defaults = nav_menu_item_defaults(rows[item_id])
        NavMenuItemRecord.objects.update_or_create(
            id=item_id,
            defaults={**defaults, "is_deleted": False, "deleted_at": None, "deleted_by": ""},
        )
    notices = NavMenuItemRecord.objects.filter(id="nav-item-notices").first()
    if notices is None:
        defaults = nav_menu_item_defaults(rows["nav-item-notices"])
        NavMenuItemRecord.objects.update_or_create(
            id="nav-item-notices",
            defaults={**defaults, "is_deleted": False, "deleted_at": None, "deleted_by": ""},
        )
    elif notices.label == "公告管理":
        data = dict(notices.data or {})
        data["label"] = "公告列表"
        notices.label = "公告列表"
        notices.data = data
        notices.save(update_fields=["label", "data"])


def noop(apps, schema_editor):
    pass


